<h1><?=htmlspecialchars($title)?></h1><form method="post" action="<?=BASE_URL.'/'.$controller?>/save" class="panel form"><input type="hidden" name="id" value="<?=$id?>"><?php foreach($fields as $name=>$label):?><label><?=htmlspecialchars($label)?><?php $type=str_contains($name,'fecha')?'date':(in_array($name,['correo'],true)?'email':(str_starts_with($name,'id_')||str_contains($name,'stock')||str_contains($name,'precio')?'number':'text'));?><input type="<?=$type?>" name="<?=$name?>" value="<?=htmlspecialchars((string)($row[$name]??($name==='estado'?'1':'')))?>" <?=$name==='ruc'?'pattern="[0-9]{11}" maxlength="11"':''?> required></label><?php endforeach;?><div><button class="btn">Guardar</button> <a href="<?=BASE_URL.'/'.$controller?>">Cancelar</a></div></form>

